const express = require('express');
const cors = require('cors');
const helmet = require('helmet');

const routes = require('./routes');
const requestLogger = require('./middleware/requestLogger');
const errorHandler = require('./middleware/errorHandler');
const { pool } = require('./config/database');

const app = express();

const allowedOrigins = (process.env.FRONTEND_URL || 'http://localhost:5173')
  .split(',')
  .map((origin) => origin.trim())
  .filter(Boolean);

app.disable('x-powered-by');

app.use(helmet());

app.use(
  cors({
    origin(origin, callback) {
      // Requests from Postman, Supertest, and server-to-server clients
      // may not provide an Origin header.
      if (!origin || allowedOrigins.includes(origin)) {
        return callback(null, true);
      }

      const error = new Error('The request origin is not allowed.');
      error.status = 403;
      error.code = 'CORS_ORIGIN_NOT_ALLOWED';
      return callback(error);
    },
    credentials: true,
  })
);

app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: false, limit: '1mb' }));
app.use(requestLogger);

app.get('/', (req, res) => {
  res.json({
    name: 'Payroll Automation API',
    status: 'running',
    apiBaseUrl: '/api',
  });
});

app.get('/api/health', async (req, res, next) => {
  try {
    await pool.query('SELECT 1');

    res.json({
      status: 'ok',
      database: 'connected',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    error.status = 503;
    error.code = 'DATABASE_UNAVAILABLE';
    error.message = 'The database is currently unavailable.';
    next(error);
  }
});

app.use('/api', routes);

app.use((req, res) => {
  res.status(404).json({
    error: 'ROUTE_NOT_FOUND',
    message: 'The requested API route was not found.',
    details: [],
  });
});

app.use(errorHandler);

module.exports = app;
```

