These are shared Sequelize models required by Member 5, but they represent data owned upstream. Only map their fields—do not add payroll calculation logic.

Important:

- `Staff.js` maps Member 1’s existing `staff` table.
- `PayPeriod.js` maps the shared period table and includes Member 4’s locking contract.
- `PayrollLine.js` maps final figures produced by Member 3.
- The database migrations must match these fields before querying them.

## 1. `Staff.js`

Path:

```text
backend/src/models/Staff.js
```

Paste:

```js
module.exports = (sequelize, DataTypes) => {
  const Staff = sequelize.define(
    'Staff',
    {
      id: {
        type: DataTypes.UUID,
        defaultValue: DataTypes.UUIDV4,
        primaryKey: true,
      },
      externalRef: {
        type: DataTypes.STRING(50),
        allowNull: false,
        unique: true,
        field: 'external_ref',
      },
      fullName: {
        type: DataTypes.STRING(150),
        allowNull: false,
        field: 'full_name',
      },
      employmentType: {
        type: DataTypes.ENUM('part_time', 'full_time'),
        allowNull: false,
        defaultValue: 'part_time',
        field: 'employment_type',
      },
      bankAccountNo: {
        type: DataTypes.STRING(100),
        allowNull: true,
        field: 'bank_account_no',
      },
      bankCode: {
        type: DataTypes.STRING(20),
        allowNull: true,
        field: 'bank_code',
      },
      cpfEligible: {
        type: DataTypes.BOOLEAN,
        allowNull: false,
        defaultValue: true,
        field: 'cpf_eligible',
      },
      status: {
        type: DataTypes.ENUM('active', 'inactive'),
        allowNull: false,
        defaultValue: 'active',
      },
    },
    {
      tableName: 'staff',
      underscored: true,
      timestamps: true,

      // Prevent accidental exposure in normal API queries.
      defaultScope: {
        attributes: {
          exclude: ['bankAccountNo'],
        },
      },

      scopes: {
        // Use this scope only in secured manager payment services.
        withBankDetails: {
          attributes: {
            include: ['bankAccountNo'],
          },
        },
      },

      indexes: [
        {
          unique: true,
          fields: ['external_ref'],
        },
        {
          fields: ['status'],
        },
      ],
    }
  );

  Staff.associate = (models) => {
    if (models.PayrollLine) {
      Staff.hasMany(models.PayrollLine, {
        foreignKey: 'staffId',
        as: 'payrollLines',
      });
    }

    if (models.Payslip) {
      Staff.hasMany(models.Payslip, {
        foreignKey: 'staffId',
        as: 'payslips',
      });
    }

    if (models.User) {
      Staff.hasOne(models.User, {
        foreignKey: 'staffId',
        as: 'userAccount',
      });
    }
  };

  return Staff;
};
```

### Important correction for secured bank queries

Because `defaultScope` excludes `bankAccountNo`, Member 5 must query it using:

```js
Staff.scope('withBankDetails').findByPk(staffId);
```

Never return that model directly in an ordinary API response.

## 2. `PayPeriod.js`

Path:

```text
backend/src/models/PayPeriod.js
```

Paste:

```js
module.exports = (sequelize, DataTypes) => {
  const PayPeriod = sequelize.define(
    'PayPeriod',
    {
      id: {
        type: DataTypes.UUID,
        defaultValue: DataTypes.UUIDV4,
        primaryKey: true,
      },
      startDate: {
        type: DataTypes.DATEONLY,
        allowNull: false,
        unique: true,
        field: 'start_date',
      },
      endDate: {
        type: DataTypes.DATEONLY,
        allowNull: false,
        field: 'end_date',
      },
      status: {
        type: DataTypes.ENUM(
          'draft',
          'validated',
          'pending_calculation',
          'pending_approval',
          'approved',
          'payment_ready'
        ),
        allowNull: false,
        defaultValue: 'draft',
      },
      validatedAt: {
        type: DataTypes.DATE,
        allowNull: true,
        field: 'validated_at',
      },
      totalGross: {
        type: DataTypes.DECIMAL(12, 2),
        allowNull: true,
        field: 'total_gross',
      },
      totalNet: {
        type: DataTypes.DECIMAL(12, 2),
        allowNull: true,
        field: 'total_net',
      },
      isLocked: {
        type: DataTypes.BOOLEAN,
        allowNull: false,
        defaultValue: false,
        field: 'is_locked',
      },
      lockedAt: {
        type: DataTypes.DATE,
        allowNull: true,
        field: 'locked_at',
      },
    },
    {
      tableName: 'pay_period',
      underscored: true,
      timestamps: true,
      indexes: [
        {
          unique: true,
          fields: ['start_date'],
        },
        {
          fields: ['status'],
        },
      ],
      validate: {
        validDateRange() {
          if (this.startDate && this.endDate && this.endDate < this.startDate) {
            throw new Error(
              'The pay-period end date cannot be before its start date.'
            );
          }
        },
        lockedPeriodHasTimestamp() {
          if (this.isLocked && !this.lockedAt) {
            throw new Error('A locked pay period must have a lockedAt value.');
          }
        },
      },
    }
  );

  PayPeriod.associate = (models) => {
    if (models.PayrollLine) {
      PayPeriod.hasMany(models.PayrollLine, {
        foreignKey: 'payPeriodId',
        as: 'payrollLines',
      });
    }

    if (models.Approval) {
      PayPeriod.hasMany(models.Approval, {
        foreignKey: 'payPeriodId',
        as: 'approvals',
      });
    }

    if (models.PaymentBatch) {
      PayPeriod.hasMany(models.PaymentBatch, {
        foreignKey: 'payPeriodId',
        as: 'paymentBatches',
      });
    }
  };

  return PayPeriod;
};
```

The current database table does not yet contain `is_locked` and `locked_at`. Do not query this model until the migration adds those columns.

