/**
 * Member 5 integration boundary.
 *
 * This adapter represents data that will eventually come from:
 * - Member 1: Staff
 * - Member 3: PayrollLine
 * - Member 4: PayPeriod and Approval
 *
 * Member 5 must not calculate or modify the approved payroll figures.
 * During integration, replace the mock functions with Sequelize queries
 * against the group members' models.
 */

const MOCK_PAY_PERIOD_ID = '10000000-0000-4000-8000-000000000001';

const mockPayPeriods = [
  {
    id: MOCK_PAY_PERIOD_ID,
    startDate: '2026-07-01',
    endDate: '2026-07-14',
    status: 'approved',
    isLocked: true,
    lockedAt: '2026-07-15T02:00:00.000Z',
  },
];

const mockApprovals = [
  {
    id: '20000000-0000-4000-8000-000000000001',
    payPeriodId: MOCK_PAY_PERIOD_ID,
    decision: 'approved',
    approvedBy: 'Demo Manager',
    decidedAt: '2026-07-15T02:00:00.000Z',
  },
];

const mockStaff = [
  {
    id: '30000000-0000-4000-8000-000000000001',
    externalRef: 'S001',
    fullName: 'Demo Staff One',
    bankCode: '7171',
    bankAccountNo: '1234567890',
    status: 'active',
  },
  {
    id: '30000000-0000-4000-8000-000000000002',
    externalRef: 'S002',
    fullName: 'Demo Staff Two',
    bankCode: '7171',
    bankAccountNo: '9876543210',
    status: 'active',
  },
];

const mockPayrollLines = [
  {
    id: '40000000-0000-4000-8000-000000000001',
    payPeriodId: MOCK_PAY_PERIOD_ID,
    staffId: '30000000-0000-4000-8000-000000000001',
    grossPay: '1250.00',
    incentivePay: '150.00',
    cpfAmount: '250.00',
    sdlAmount: '2.00',
    otherDeduction: '0.00',
    netPay: '1148.00',
    status: 'ok',
  },
  {
    id: '40000000-0000-4000-8000-000000000002',
    payPeriodId: MOCK_PAY_PERIOD_ID,
    staffId: '30000000-0000-4000-8000-000000000002',
    grossPay: '980.00',
    incentivePay: '80.00',
    cpfAmount: '196.00',
    sdlAmount: '2.00',
    otherDeduction: '0.00',
    netPay: '862.00',
    status: 'ok',
  },
];

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

async function getPayPeriodById(payPeriodId) {
  const payPeriod = mockPayPeriods.find(
    (item) => item.id === payPeriodId
  );

  return payPeriod ? clone(payPeriod) : null;
}

async function getApprovalForPayPeriod(payPeriodId) {
  const approval = mockApprovals.find(
    (item) =>
      item.payPeriodId === payPeriodId &&
      item.decision === 'approved'
  );

  return approval ? clone(approval) : null;
}

async function getPayrollLinesForPayPeriod(payPeriodId) {
  return clone(
    mockPayrollLines.filter(
      (item) => item.payPeriodId === payPeriodId
    )
  );
}

async function getStaffByIds(staffIds) {
  return clone(
    mockStaff.filter((item) => staffIds.includes(item.id))
  );
}

async function getApprovedPayPeriods() {
  return clone(
    mockPayPeriods.filter(
      (item) => item.status === 'approved' && item.isLocked
    )
  );
}

async function updateStaffBankDetails(staffId, bankDetails) {
  const staff = mockStaff.find((item) => item.id === staffId);

  if (!staff) {
    return null;
  }

  staff.bankCode = bankDetails.bankCode;
  staff.bankAccountNo = bankDetails.bankAccountNo;

  return clone(staff);
}

/**
 * Integration placeholder.
 *
 * Member 4 will eventually provide the real Sequelize PayPeriod update.
 * Member 5 should call this only after successful HRMS synchronisation.
 */
async function markPayPeriodPaymentReady(payPeriodId) {
  const payPeriod = mockPayPeriods.find(
    (item) => item.id === payPeriodId
  );

  if (!payPeriod) {
    return null;
  }

  payPeriod.status = 'payment_ready';
  return clone(payPeriod);
}

module.exports = {
  MOCK_PAY_PERIOD_ID,
  getPayPeriodById,
  getApprovalForPayPeriod,
  getPayrollLinesForPayPeriod,
  getStaffByIds,
  getApprovedPayPeriods,
  updateStaffBankDetails,
  markPayPeriodPaymentReady,
};
```

