We have already completed these Member 5 models:

```text
PaymentBatch.js
Payslip.js
Invoice.js
InvoiceItem.js
```

Complete the model layer with `User.js` and `AuditLog.js`.

## 1. `User.js`

Create:

```text
backend/src/models/User.js
```

Paste:

```js
module.exports = (sequelize, DataTypes) => {
  const User = sequelize.define(
    'User',
    {
      id: {
        type: DataTypes.UUID,
        defaultValue: DataTypes.UUIDV4,
        primaryKey: true,
      },

      fullName: {
        type: DataTypes.STRING(150),
        allowNull: false,
        field: 'full_name',
        validate: {
          notEmpty: true,
          len: [2, 150],
        },
      },

      email: {
        type: DataTypes.STRING(150),
        allowNull: false,
        unique: true,
        validate: {
          isEmail: true,
        },
        set(value) {
          this.setDataValue('email', value.trim().toLowerCase());
        },
      },

      passwordHash: {
        type: DataTypes.STRING(255),
        allowNull: false,
        field: 'password_hash',
      },

      role: {
        type: DataTypes.ENUM('manager', 'staff'),
        allowNull: false,
        defaultValue: 'staff',
      },

      /**
       * Integration placeholder.
       *
       * Staff users will eventually be linked to Member 1's Staff model.
       * Manager accounts may leave this field null.
       */
      staffId: {
        type: DataTypes.UUID,
        allowNull: true,
        unique: true,
        field: 'staff_id',
      },

      status: {
        type: DataTypes.ENUM('active', 'disabled'),
        allowNull: false,
        defaultValue: 'active',
      },

      lastLoginAt: {
        type: DataTypes.DATE,
        allowNull: true,
        field: 'last_login_at',
      },
    },
    {
      tableName: 'users',
      underscored: true,
      timestamps: true,

      // Never return passwordHash in ordinary queries.
      defaultScope: {
        attributes: {
          exclude: ['passwordHash'],
        },
      },

      // Authentication service must explicitly request this scope.
      scopes: {
        withPassword: {
          attributes: {
            include: ['passwordHash'],
          },
        },
      },

      indexes: [
        {
          unique: true,
          fields: ['email'],
        },
        {
          unique: true,
          fields: ['staff_id'],
        },
        {
          fields: ['role'],
        },
        {
          fields: ['status'],
        },
      ],

      validate: {
        staffRoleRequiresStaffId() {
          if (this.role === 'staff' && !this.staffId) {
            throw new Error(
              'A staff user account must be linked to a staff ID.'
            );
          }
        },
      },
    }
  );

  User.associate = (models) => {
    // This association activates later when Member 1's Staff model exists.
    if (models.Staff) {
      User.belongsTo(models.Staff, {
        foreignKey: 'staffId',
        as: 'staffProfile',
      });
    }

    if (models.PaymentBatch) {
      User.hasMany(models.PaymentBatch, {
        foreignKey: 'generatedBy',
        as: 'generatedPaymentBatches',
      });

      User.hasMany(models.PaymentBatch, {
        foreignKey: 'cancelledBy',
        as: 'cancelledPaymentBatches',
      });
    }

    if (models.Invoice) {
      User.hasMany(models.Invoice, {
        foreignKey: 'createdBy',
        as: 'createdInvoices',
      });
    }

    if (models.AuditLog) {
      User.hasMany(models.AuditLog, {
        foreignKey: 'userId',
        as: 'auditLogs',
      });
    }
  };

  return User;
};
```

The authentication service will later query passwords with:

```js
User.scope('withPassword').findOne({
  where: { email },
});
```

Do not add a Sequelize hook that hashes passwords. The authentication service will call bcrypt explicitly so hashing behavior is easier to test.

