## Create `models/index.js`

Path:

```text
backend/src/models/index.js
```

Paste:

```js
const path = require('path');
const { Sequelize, DataTypes } = require('sequelize');

require('dotenv').config({
  path: path.resolve(__dirname, '../../../.env'),
});

if (!process.env.DATABASE_URL) {
  throw new Error(
    'DATABASE_URL is missing from payroll-automation/.env.'
  );
}

const sequelize = new Sequelize(process.env.DATABASE_URL, {
  dialect: 'postgres',
  logging: process.env.NODE_ENV === 'development' ? console.log : false,
  dialectOptions:
    process.env.NODE_ENV === 'production'
      ? {
          ssl: {
            require: true,
            rejectUnauthorized: false,
          },
        }
      : {},
});

// Register only Member 5 and shared-authentication models.
const models = {
  User: require('./User')(sequelize, DataTypes),
  PaymentBatch: require('./PaymentBatch')(sequelize, DataTypes),
  Payslip: require('./Payslip')(sequelize, DataTypes),
  Invoice: require('./Invoice')(sequelize, DataTypes),
  InvoiceItem: require('./InvoiceItem')(sequelize, DataTypes),
  AuditLog: require('./AuditLog')(sequelize, DataTypes),
};

// Run associations after every model has been registered.
Object.values(models).forEach((model) => {
  if (typeof model.associate === 'function') {
    model.associate(models);
  }
});

module.exports = {
  sequelize,
  Sequelize,
  ...models,
};
```

## Check dependencies

Your backend `package.json` must contain:

```json
"pg": "^8.12.0",
"pg-hstore": "^2.3.4",
"sequelize": "^6.37.3"
```

Then run inside `backend`:

```powershell
npm install
```

## Test only the Sequelize connection

From the `backend` directory:

```powershell
node -e "const { sequelize } = require('./src/models'); sequelize.authenticate().then(() => { console.log('Sequelize connected successfully'); return sequelize.close(); }).catch((error) => { console.error(error.message); process.exit(1); });"
```

Expected result:

```text
Sequelize connected successfully
```

This does not create, change, or delete tables.

After the connection succeeds, the next step is a Member 5 migration that creates only:

```text
users
payment_batch
payslip
invoice
invoice_item
audit_log
```

