Next, seed standalone development data through Sequelize. Passwords will come from `.env`, not source code.

## 1. Add local seed variables

Add to `payroll-automation/.env`:

```env
SEED_MANAGER_EMAIL=manager@example.com
SEED_MANAGER_PASSWORD=replace_with_your_manager_test_password

SEED_STAFF_EMAIL=staff@example.com
SEED_STAFF_PASSWORD=replace_with_your_staff_test_password
```

Use test passwords with at least eight characters, letters, numbers, and a symbol. Do not send them to me or commit `.env`.

Add safe placeholders to `.env.example`:

```env
SEED_MANAGER_EMAIL=manager@example.com
SEED_MANAGER_PASSWORD=replace_with_manager_test_password

SEED_STAFF_EMAIL=staff@example.com
SEED_STAFF_PASSWORD=replace_with_staff_test_password
```

## 2. Create the seed script

Create:

```text
backend/src/db/seeds/005_member5_seed.js
```

Paste:

```js
const bcrypt = require('bcrypt');

const {
  sequelize,
  User,
  Approval,
} = require('../../models');

const REQUIRED_ENVIRONMENT_VARIABLES = [
  'SEED_MANAGER_EMAIL',
  'SEED_MANAGER_PASSWORD',
  'SEED_STAFF_EMAIL',
  'SEED_STAFF_PASSWORD',
];

function checkEnvironment() {
  const missingVariables = REQUIRED_ENVIRONMENT_VARIABLES.filter(
    (name) => !process.env[name]?.trim()
  );

  if (missingVariables.length > 0) {
    throw new Error(
      `Missing environment variables: ${missingVariables.join(', ')}`
    );
  }
}

async function upsertUser({
  fullName,
  email,
  passwordHash,
  role,
  staffId = null,
  transaction,
}) {
  const normalisedEmail = email.trim().toLowerCase();

  const existingUser = await User.unscoped().findOne({
    where: {
      email: normalisedEmail,
    },
    transaction,
  });

  if (existingUser) {
    await existingUser.update(
      {
        fullName,
        passwordHash,
        role,
        staffId,
        status: 'active',
      },
      {
        transaction,
      }
    );

    return existingUser;
  }

  return User.create(
    {
      fullName,
      email: normalisedEmail,
      passwordHash,
      role,
      staffId,
      status: 'active',
    },
    {
      transaction,
    }
  );
}

async function seed() {
  checkEnvironment();

  const transaction = await sequelize.transaction();

  try {
    const managerPasswordHash = await bcrypt.hash(
      process.env.SEED_MANAGER_PASSWORD,
      10
    );

    const staffPasswordHash = await bcrypt.hash(
      process.env.SEED_STAFF_PASSWORD,
      10
    );

