    await sequelize.close();
  }
}

seed().catch((error) => {
  console.error('Member 5 seed failed:', error.message);
  process.exit(1);
});
```

## 3. Add the seed command

In `backend/package.json`, add this script:

```json
"db:seed:member5": "node src/db/seeds/005_member5_seed.js"
```

